:root {
  --bg: #04070d;
  --panel: rgba(8, 12, 18, 0.72);
  --line: rgba(166, 203, 255, 0.3);
  --text: #edf5ff;
  --accent: #d9a441;
  --danger: #ff4d4d;
  --glow: rgba(255, 90, 90, 0.7);
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: radial-gradient(circle at top, #0d1526 0%, #04070d 40%, #020508 100%);
  color: var(--text);
  font-family: Inter, "Segoe UI", sans-serif;
}

body {
  position: relative;
}

canvas {
  display: block;
  width: 100vw;
  height: 100vh;
  background: #04070d;
}

#ui {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.8rem;
  pointer-events: none;
  text-align: center;
  z-index: 2;
  background: radial-gradient(circle at center, rgba(8, 12, 22, 0.2), rgba(2, 5, 11, 0.75));
}

#title,
#subtitle,
#hud,
#startBtn {
  pointer-events: auto;
}

#title {
  font-size: clamp(2rem, 4vw, 4rem);
  letter-spacing: 0.28rem;
  font-weight: 900;
  text-shadow: 0 0 18px rgba(255, 120, 120, 0.5);
}

#subtitle {
  font-size: 1rem;
  letter-spacing: 0.25rem;
  text-transform: uppercase;
  color: rgba(237, 245, 255, 0.8);
}

#hud {
  position: absolute;
  top: 1rem;
  left: 1rem;
  padding: 0.8rem 1rem;
  border: 1px solid var(--line);
  background: var(--panel);
  border-radius: 12px;
  backdrop-filter: blur(4px);
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  min-width: 160px;
  box-shadow: 0 0 20px rgba(19, 29, 40, 0.5);
}

#count, #threat {
  font-weight: 700;
  color: var(--accent);
}

#startBtn {
  border: 1px solid rgba(255, 182, 110, 0.65);
  background: rgba(18, 13, 9, 0.8);
  color: var(--text);
  font-size: 1rem;
  letter-spacing: 0.12rem;
  text-transform: uppercase;
  padding: 0.9rem 1.4rem;
  border-radius: 999px;
  cursor: pointer;
  box-shadow: 0 0 20px rgba(255, 167, 84, 0.18);
  transition: transform 0.15s ease, box-shadow 0.2s ease;
}

#startBtn:hover {
  transform: translateY(-1px) scale(1.02);
  box-shadow: 0 0 28px rgba(255, 167, 84, 0.25);
}

#messageBox {
  position: absolute;
  left: 50%;
  bottom: 3rem;
  transform: translateX(-50%);
  z-index: 4;
  padding: 1rem 1.4rem;
  background: rgba(25, 14, 18, 0.82);
  border: 1px solid rgba(255, 133, 133, 0.24);
  border-radius: 14px;
  box-shadow: 0 0 20px rgba(255, 113, 113, 0.18);
}

#messageText {
  font-size: 1.05rem;
  letter-spacing: 0.08rem;
  text-transform: uppercase;
  color: #ffe9e9;
}

