}
#count, #threat { color: var(--amber); font-weight: 500; }
#threat { color: #a7c7ae; }
#messageBox {
  position: absolute;
  z-index: 4;
  left: 50%;
  bottom: max(2rem, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  max-width: calc(100vw - 2rem);
  padding: 0.9rem 1.3rem;
  border: 1px solid rgba(239, 86, 81, 0.42);
